/* Auto-extracted from smart-report-prototype.html — keep in sync. */
import fs from 'fs';
import path from 'path';

/**
 * Real Sobhana wordmark, inlined as a data URI so the same HTML works both when
 * Puppeteer prints it and when it is served over HTTP to a patient's phone.
 * Same file + path-candidate approach as billPdfService.getLogoDataUri(); kept
 * local rather than imported because that module pulls in prisma and Puppeteer.
 */
let _brandLogo: string | null = null;
export function getBrandLogoDataUri(): string {
  if (_brandLogo !== null) return _brandLogo;
  for (const p of [
    path.join(__dirname, '../../../public/images/sobhana-logo-cropped.png'),
    path.join(__dirname, '../../../../public/images/sobhana-logo-cropped.png'),
    path.join(process.cwd(), 'public/images/sobhana-logo-cropped.png'),
  ]) {
    try {
      if (fs.existsSync(p)) {
        _brandLogo = `data:image/png;base64,${fs.readFileSync(p).toString('base64')}`;
        return _brandLogo;
      }
    } catch { /* try next */ }
  }
  _brandLogo = '';   // logo simply won't render; report still ships
  return _brandLogo;
}

