export const REPORT_CSS = `:root{
  --g1:#1E6CA8; --g2:#185484; --g3:#123F63; --gdark:#123F63; --brand-red:#E42424;
  --ink:#1A1A1A; --sub:#7A8189; --lbl:#9AA0A6; --line:#E8EAED;
  --ok-b:#E6F4EA; --ok-t:#1E8E3E; --bad-b:#FCE8E6; --bad-t:#D93025;
  --pen-b:#E8F0FE; --pen-t:#1A73E8; --bor-b:#FEF7E0; --bor-t:#B06000;
  --blue-box:#E8F4FA;
}
*{box-sizing:border-box}
body{margin:0;background:#DFE3E8;color:var(--ink);
 font:13.5px/1.55 "Poppins","Avenir Next","Segoe UI",system-ui,sans-serif;-webkit-font-smoothing:antialiased}
.emo{font-family:"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif;font-style:normal}
.hi{fill:currentColor;display:block}
.page{width:794px;height:1123px;margin:22px auto;background:#fff;position:relative;overflow:hidden;
 box-shadow:0 1px 3px rgba(0,0,0,.12),0 14px 34px rgba(0,0,0,.10);display:flex;flex-direction:column}
.topbar{height:7px;background:linear-gradient(90deg,var(--g1),var(--g2) 55%,var(--g3));flex:none}
.phead{display:flex;align-items:center;justify-content:space-between;padding:13px 40px 11px;flex:none}
.coverart{position:absolute;right:44px;bottom:98px;width:530px;height:480px;display:flex;
  align-items:flex-end;justify-content:flex-end;overflow:hidden}
.coverart svg{height:100%;width:auto;max-width:100%}
/* Each drawing frames its figure differently — the male carries a pale bench that
   inflates its box, the child fills its own. Tuned so the PEOPLE match in size. */
.coverart.v-male svg{height:96%}
.coverart.v-female svg{height:86%}
.coverart.v-child svg{height:74%}
.futureart{display:flex;align-items:center;justify-content:center;padding:6px 12px 0}
.futureart svg{width:100%;height:auto;max-height:200px}
.scorenote{font-size:9.5px;line-height:1.55;color:#9AA0A6;margin:9px 0 0;max-width:660px;padding-top:8px;border-top:1px solid #EEF0F2}
.logo{display:flex;align-items:center;gap:9px}
.brandlogo{height:30px;width:110px;flex:none}
.cover .brandlogo{height:44px;width:162px}
.logo b{display:block;font-size:15.5px;font-weight:700;line-height:1.15;color:#185484;letter-spacing:-.2px}
.logo span{display:block;font-size:9px;color:#5F6368}
.web{display:flex;align-items:center;gap:7px;font-size:11.5px;color:#5F6368}
.web .globe{width:22px;height:22px;border-radius:50%;background:#E6F4EA;display:grid;place-items:center}
.strip{display:grid;grid-template-columns:1.25fr 1fr 1fr .9fr;gap:0 20px;padding:9px 40px;
 border-top:1px solid var(--line);border-bottom:1px solid var(--line);flex:none}
.strip div span{display:block;font-size:9.5px;color:var(--lbl);margin-bottom:1px}
.strip div b{font-size:12.5px;font-weight:600}
.strip div:last-child{text-align:right}
.content{padding:22px 40px 0;flex:1;min-height:0}
.pfoot{display:flex;justify-content:space-between;align-items:center;margin:0 40px;padding:9px 0 14px;
 border-top:1px solid var(--line);font-size:9.5px;color:var(--lbl);flex:none}
.pfoot b{font-size:11px;color:#5F6368;font-weight:600}
h1{font-size:29px;font-weight:700;letter-spacing:-.7px;margin:0 0 3px}
p.sub{margin:0 0 18px;font-size:13px;color:var(--sub)}
h2{font-size:14.5px;font-weight:700;margin:20px 0 10px}
h2:first-child{margin-top:0}
.aitag{display:inline-flex;align-items:center;gap:4px;background:#E8F1F8;color:#185484;border-radius:5px;
 padding:2px 7px;font-size:9.5px;font-weight:700;letter-spacing:.3px;vertical-align:middle;margin-left:7px}
.pill{display:inline-block;font-size:9.5px;font-weight:600;border-radius:4px;padding:2px 7px;margin-right:4px}
.p-ok{background:var(--ok-b);color:var(--ok-t)} .p-bad{background:var(--bad-b);color:var(--bad-t)}
.p-pen{background:var(--pen-b);color:var(--pen-t)} .p-bor{background:var(--bor-b);color:var(--bor-t)}
.p-mild{background:var(--bor-b);color:var(--bor-t)}

/* cover */
.cover{position:relative;flex:1;padding:44px 46px 0}
.crosses{position:absolute;top:40px;right:46px;width:230px;height:230px}
.cx{position:absolute;background:#EFF1F3;
 clip-path:polygon(35% 0,65% 0,65% 35%,100% 35%,100% 65%,65% 65%,65% 100%,35% 100%,35% 65%,0 65%,0 35%,35% 35%)}
.cx.g{background:#185484}
.script{font:italic 400 58px/1 "Snell Roundhand","Brush Script MT","Segoe Script",cursive;color:var(--brand-red);margin:50px 0 -12px}
.cover h1{font-size:56px;letter-spacing:-2px;line-height:1.05;margin:0}
.aibadge{display:inline-flex;align-items:center;gap:6px;background:#E8F1F8;color:#185484;border-radius:6px;
 padding:5px 11px;font-size:12.5px;font-weight:600;margin-top:15px}
.who{margin-top:34px}
.who .lb{font-size:12.5px;color:var(--sub)}
.who b{display:block;font-size:26px;font-weight:700;margin:1px 0 2px;letter-spacing:-.4px}
.who .mi{font-size:13px;color:var(--sub)}
.hexwrap{position:absolute;left:0;right:0;top:430px;height:430px}
.hex{position:absolute;clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);overflow:hidden}
.coverfoot{position:absolute;left:46px;right:46px;bottom:34px;display:flex;justify-content:space-between;align-items:flex-end}
.coverfoot .addr{font-size:10.5px;color:#5F6368;line-height:1.6}
.coverfoot .addr b{display:block;font-size:12.5px;color:var(--ink);margin-bottom:3px}
.qr{width:92px;height:92px}
.qrbox span{display:block;font-size:9px;color:var(--lbl);margin-top:5px;line-height:1.35}

/* page 01 */
.metrics{display:grid;grid-template-columns:1fr 1fr 1.35fr;gap:11px}
.metric{border-radius:11px;padding:13px 15px 15px;position:relative;min-height:88px}
.m-w{background:#E9F3FA} .m-h{background:#FDF6E0} .m-b{background:#F4EEFB}
.metric .mt{font-size:12.5px;font-weight:600}
.metric .ic{position:absolute;top:12px;right:13px;opacity:.75}
.metric .mv{font-size:26px;font-weight:700;margin-top:12px;letter-spacing:-.6px}
.metric .mv small{font-size:12.5px;font-weight:600;color:#5F6368}
.metric .mv em{font-style:normal;font-size:13px;font-weight:600;color:#D93025}
.tscore{margin-top:16px}
.tscore h3{font-size:13px;font-weight:700;margin:0 0 4px}
.tscore p{margin:0;font-size:12.3px;color:#4A5056}
.tscore p b{color:var(--ink)}
.bodywrap{display:grid;grid-template-columns:1fr 262px 1fr;gap:6px;align-items:center;margin-top:18px}
.tcol{display:flex;flex-direction:column;gap:62px}
.tile{display:flex;align-items:center;gap:10px}
.tile .ico{width:46px;height:46px;border-radius:50%;background:#fff;border:1px solid var(--line);
 display:grid;place-items:center;flex:none;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.tile .tx b{display:block;font-size:11.6px;font-weight:600;line-height:1.3}
.tile .tx .bd{margin-top:3px}
.figure{display:grid;place-items:center}
.figure .bodyfig{width:250px;display:block}

/* page 02 */
.ess{display:grid;grid-template-columns:1fr 1fr 1.75fr;gap:11px}
.ecard{border:1px solid var(--line);border-radius:11px;padding:13px 14px;min-height:116px}
.ecard .eh{display:flex;align-items:center;gap:8px}
.ecard b.tt{font-size:12.5px;font-weight:600}
.ecard p{margin:5px 0 0;font-size:10px;color:var(--lbl);line-height:1.45}
.ecard .val{font-size:23px;font-weight:700;margin-top:10px;letter-spacing:-.5px}
.three{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}
.three div{border-left:1px solid var(--line);padding-left:11px}
.three div:first-child{border-left:0;padding-left:0}
.three span{display:block;font-size:10px;color:var(--lbl)}
.three b{font-size:15.5px;font-weight:700}
.infobox{background:var(--blue-box);border-radius:11px;padding:14px 16px;margin-top:13px}
.infobox b{display:block;font-size:13px;margin-bottom:5px}
.infobox p{margin:0;font-size:11.5px;color:#40474D;line-height:1.6}
.macros{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}
.goalbox{background:var(--blue-box);border-radius:11px;padding:15px 17px;margin-top:13px}
.goalrow{display:grid;grid-template-columns:1.15fr repeat(3,1fr);gap:12px;align-items:end}
.goalrow>b{font-size:14.5px;font-weight:700;line-height:1.3}
.goalrow div span{display:block;font-size:10px;color:var(--lbl)}
.goalrow div b{font-size:15.5px;font-weight:700}
.goalbox hr{border:0;border-top:1px solid #CFE4EE;margin:11px 0 9px}
.goalbox p{margin:0;font-size:11.5px;color:#40474D}

/* pages 03-04 finding cards */
.fcard{border:1px solid var(--line);border-radius:10px;padding:7px 12px;margin-bottom:6px}
.fhead{display:flex;align-items:center;gap:10px}
.fhead .ico{width:30px;height:30px;border-radius:50%;background:#fff;border:1px solid var(--line);
 display:grid;place-items:center;flex:none}
.fhead .nm{flex:1}
.fhead .nm b{font-size:12.5px;font-weight:600}
.fhead .nm span{display:block;font-size:9.5px;color:var(--lbl)}
.fhead .rv{text-align:right;white-space:nowrap}
.fhead .rv b{font-size:16px;font-weight:700;letter-spacing:-.3px}
.fhead .rv small{font-size:10px;color:var(--lbl);font-weight:500}
.gauge{margin:6px 0 4px}
.gtrack{height:6px;border-radius:3px;display:grid;grid-template-columns:1fr 1.6fr 1fr;overflow:hidden}
.gtrack i{display:block}
.gtrack .lo{background:#D6E4F7} .gtrack .no{background:#BFE7C9} .gtrack .hi{background:#F8CFCB}
.gmark{position:relative;height:0}
.gmark i{position:absolute;top:-11px;width:2px;height:16px;background:var(--ink);border-radius:1px}
.gmark i::after{content:"";position:absolute;top:-4px;left:-3px;width:8px;height:8px;border-radius:50%;background:var(--ink)}
.glabels{display:flex;justify-content:space-between;font-size:8px;color:var(--lbl);margin-top:3px}
.fcard p{margin:3px 0 0;font-size:10.8px;color:#40474D;line-height:1.45}
.ftrend{display:inline-block;margin-top:4px;font-size:9.5px;background:#F4F6F8;border-radius:5px;padding:2px 6px;color:#5F6368}

/* page 05 */
.trendtab{width:100%;border-collapse:collapse;font-size:11.8px}
.trendtab th{text-align:left;font-size:9px;text-transform:uppercase;letter-spacing:.6px;color:var(--lbl);
 font-weight:600;padding:6px 8px;border-bottom:1px solid var(--line)}
.trendtab td{padding:6px 8px;border-bottom:1px solid #F3F5F7}
.trendtab td.v{text-align:right;font-weight:700} .trendtab td.u{color:#7A8189} .trendtab td.s{text-align:right}
.up{color:#D93025} .down{color:#1A73E8}
.sumgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.sumcard{border-radius:11px;padding:15px 16px}
.s-good{background:#EFF8F1} .s-watch{background:#FDF1F0}
.sumcard h3{margin:0 0 9px;font-size:13.5px;font-weight:700}
.sumcard ul{margin:0;padding:0;list-style:none}
.sumcard li{font-size:11.6px;padding-left:18px;position:relative;margin-bottom:6px;color:#40474D}
.sumcard li::before{position:absolute;left:0;font-weight:700}
.s-good li::before{content:"✓";color:var(--ok-t)} .s-watch li::before{content:"!";color:var(--bad-t)}

/* page 06 */
.advgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.adv{border-radius:12px;padding:16px 17px}
.a-diet{background:#EFF7E9} .a-life{background:#FDF8E4}
.adv h3{margin:0 0 10px;font-size:15.5px;font-weight:700}
.adv .art{display:grid;place-items:center;margin:2px 0 12px}
.blk{margin-bottom:12px}
.blk b{display:block;font-size:12.3px;font-weight:700;margin-bottom:5px}
.blk div{font-size:11.2px;color:#40474D;padding-left:17px;position:relative;margin-bottom:4px;line-height:1.5}
.blk div.do::before{content:"✓";position:absolute;left:0;color:var(--ok-t);font-weight:700}
.blk div.no::before{content:"✕";position:absolute;left:0;color:var(--bad-t);font-weight:700}
.future{background:var(--blue-box);border-radius:12px;padding:16px 18px;margin-top:12px;
 display:grid;grid-template-columns:120px 1fr;gap:16px;align-items:center}
.future h3{margin:0 0 9px;font-size:15.5px;font-weight:700}
.future .ln{font-size:11.4px;color:#40474D;line-height:1.6;margin-bottom:7px}
.future .ln b{font-weight:700;color:var(--ink)}
.disclaim{background:#F4F6F8;border-radius:10px;padding:11px 14px;margin-top:12px;font-size:10.2px;color:#5F6368;line-height:1.6}
.tag{position:fixed;top:9px;left:9px;background:#1A1A1A;color:#fff;font-size:11px;padding:5px 10px;border-radius:6px;z-index:9;opacity:.85}
@media print{body{background:#fff}.tag{display:none}.page{margin:0;box-shadow:none;page-break-after:always}@page{size:A4;margin:0}}`;


